INSERT INTO listening_lesson (id, lesson_no, title, audio_key, duration_ms, sort_order) VALUES ('listen-14', 14, '第14課 听力训练', 'listening/listening-lesson-14.mp3', 144266, 0);
INSERT INTO listening_section (id, lesson_id, section_no, kind, instruction, audio_start_ms, audio_end_ms, example_prompt, example_answer) VALUES ('lsn14-s1', 'listen-14', 1, 'text', '听录音，根据录音中的内容仿照例子写下相应的时间。', 18428, 89865, '今、9時40分です。', '');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn14-s1-q1', 'lsn14-s1', 1, '明日のオンライン講座は＿＿＿＿です。', '[]'::jsonb, '1時間半|1時間30分');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn14-s1-q2', 'lsn14-s1', 2, '夏休みは＿＿＿＿です。', '[]'::jsonb, '16日から29日まで|16日〜29日|16日29日|16日から29日');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn14-s1-q3', 'lsn14-s1', 3, 'この映画の長さは、＿＿＿＿です。', '[]'::jsonb, '2時間半|2時間30分');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn14-s1-l1', 'lsn14-s1', 1, 'A', 18728, 22602, 'すみません、今何時ですか。', 'A：请问现在几点？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn14-s1-l2', 'lsn14-s1', 2, 'B', 23382, 26517, '9時40分です。', 'B：9点40分。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn14-s1-l3', 'lsn14-s1', 3, 'A', 32515, 41356, '明日のオンライン講座は何時間ありますか。', 'A：明天的线上讲座有多长时间？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn14-s1-l4', 'lsn14-s1', 4, 'B', 42186, 44467, '1時間半です。', 'B：一个半小时。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn14-s1-l5', 'lsn14-s1', 5, 'A', 50448, 60406, 'もう15日ですか？明日から夏休みですね。', 'A：已经15号了吗？明天开始放暑假了。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn14-s1-l6', 'lsn14-s1', 6, 'B', 61463, 69066, 'あ、本当だ。二週間ありますから、29日までですね。', 'B：啊，真的。有两周时间，所以放到29号。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn14-s1-l7', 'lsn14-s1', 7, 'A', 75082, 84858, 'この映画、長いですね。もう疲れました。', 'A：这部电影真长啊。我都累了。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn14-s1-l8', 'lsn14-s1', 8, 'B', 85922, 89165, '私も。2時間半ですからね。', 'B：我也是。毕竟两个半小时。');
INSERT INTO listening_section (id, lesson_id, section_no, kind, instruction, audio_start_ms, audio_end_ms, example_prompt, example_answer) VALUES ('lsn14-s2', 'listen-14', 2, 'text', '高桥先生从去年到今年4月发生了哪些变化？根据录音中的内容，用日语填写画线处的内容。', 105193, 136512, '', '');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn14-s2-q1', 'lsn14-s2', 1, '昇格の理由：＿＿＿＿', '[]'::jsonb, '実績がいい|実績がよい|実績');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn14-s2-q2', 'lsn14-s2', 2, '今年4月のSKL社での役職：＿＿＿＿', '[]'::jsonb, '課長');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn14-s2-q3', 'lsn14-s2', 3, '今年の仕事の量：＿＿＿＿', '[]'::jsonb, '多い|多くなりました');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn14-s2-q4', 'lsn14-s2', 4, '性格：＿＿＿＿', '[]'::jsonb, '真面目・勤勉|真面目|勤勉');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn14-s2-q5', 'lsn14-s2', 5, '今年の休み：＿＿＿＿', '[]'::jsonb, '日曜日|日曜');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn14-s2-l1', 'lsn14-s2', 1, '', 105493, 111918, '高橋さんはSKL社の社員です。', '高桥是SKL公司的员工。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn14-s2-l2', 'lsn14-s2', 2, '', 113161, 115471, 'とても真面目で、勤勉です。', '非常认真、勤奋。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn14-s2-l3', 'lsn14-s2', 3, '', 116837, 122284, '実績がよかったので、今年の4月から課長になりました。', '因为业绩好，今年4月起当上了课长。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn14-s2-l4', 'lsn14-s2', 4, '', 122285, 126398, 'そして、仕事も多くなりました。', '而且工作也变多了。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn14-s2-l5', 'lsn14-s2', 5, '', 126399, 131602, 'なかなか終わりませんから、土曜日も仕事です。', '工作总也做不完，所以周六也要上班。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn14-s2-l6', 'lsn14-s2', 6, '', 132937, 135812, '休みは日曜日だけになりました。', '休息日只剩下周日了。');
